"""Synthetic resident rules, not authentication."""
def register(repo, name, zone):
    if not name.strip() or not zone.strip():
        raise ValueError("name and delivery zone required")
    return repo.insert("residents", {"name": name, "zone": zone, "active": True, "points": 0})

def require_active(repo, resident_id):
    row = repo.get("residents", resident_id)
    if row is None or not row["active"]:
        raise ValueError("resident inactive or missing")
    return row

"""Synthetic saleable catalog and freeze action."""
def list_saleable(repo):
    return repo.find("catalog", lambda row: row["saleable"])

def require_saleable(repo, product_id):
    row = repo.get("catalog", product_id)
    if row is None or not row["saleable"]:
        raise ValueError("product unavailable")
    return row

def freeze(repo, product_id):
    row = repo.get("catalog", product_id)
    if row is None:
        raise ValueError("product missing")
    row["saleable"] = False

"""Synthetic integer-cent pricing without a tax engine."""
def subtotal(lines):
    for line in lines:
        if type(line["unit_cents"]) is not int or line["unit_cents"] <= 0:
            raise ValueError("positive integer cents required")
    return sum(line["unit_cents"] * line["quantity"] for line in lines)

"""Synthetic cart lines indexed by resident and product."""
def put(repo, resident_id, product_id, quantity):
    if type(quantity) is not int or quantity <= 0:
        raise ValueError("positive integer quantity required")
    rows = repo.find("cart_lines", lambda row: row["resident_id"] == resident_id and row["product_id"] == product_id)
    if rows:
        rows[0]["quantity"] = quantity
        return rows[0]
    return repo.insert("cart_lines", {"resident_id": resident_id, "product_id": product_id, "quantity": quantity})

def lines_for(repo, resident_id):
    return repo.find("cart_lines", lambda row: row["resident_id"] == resident_id)

"""Synthetic owner-bound fixed discounts; expiry equal to now is accepted."""
def discount(repo, coupon_id, resident_id, amount, now):
    if coupon_id is None:
        return 0
    row = repo.get("coupons", coupon_id)
    if row is None or row["resident_id"] != resident_id or not row["active"]:
        raise ValueError("coupon unavailable")
    if row["expires_at"] < now or amount < row["minimum_cents"]:
        raise ValueError("coupon condition not met")
    return min(amount, row["discount_cents"])

"""Synthetic available/reserved counters; caller supplies transaction."""
def stock(repo, product_id):
    rows = repo.find("inventory", lambda row: row["product_id"] == product_id)
    if not rows:
        raise ValueError("stock missing")
    return rows[0]

def reserve(repo, product_id, quantity):
    row = stock(repo, product_id)
    if row["available"] < quantity:
        raise ValueError("stock insufficient")
    row["available"] -= quantity
    row["reserved"] += quantity

def release(repo, product_id, quantity):
    row = stock(repo, product_id)
    if row["reserved"] < quantity:
        raise ValueError("reserved stock insufficient")
    row["reserved"] -= quantity
    row["available"] += quantity

def consume(repo, product_id, quantity):
    row = stock(repo, product_id)
    if row["reserved"] < quantity:
        raise ValueError("reserved stock insufficient")
    row["reserved"] -= quantity
